import type { AuthSession } from "../../src/components/accounts/types";
import type { MfaFactor } from "../../src/lib/auth/mfa-enrollment";

const listeners = new Set<(event: string, session: AuthSession | null) => void>();
let session: AuthSession | null = null;
export const fixtureQr = `data:image/svg+xml;utf-8,<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by SVGo -->
<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" fill="white"/><path d="M20 20h40v40H20z" fill="black"/></svg>
`;
type Failure = "error" | "throw" | "missing" | null;
const mfaState = {
  verified: false,
  factors: [{ id: "verified-fixture", factor_type: "totp", status: "verified" }] as MfaFactor[],
  qrCode: fixtureQr as string | null,
  listFailure: null as Failure,
  unenrollFailure: null as Failure,
  calls: [] as { action: string; factorId?: string }[],
};
export const fixture = {
  mfa: mfaState,
  session(value: AuthSession | null) {
    session = value;
    document.cookie = `fixture-user=${value?.user.id ?? ""}; Path=/; SameSite=Lax`;
    for (const listener of listeners) listener(value ? "SIGNED_IN" : "SIGNED_OUT", value);
  },
};
const client = { auth: {
  getSession: async () => ({ data: { session } }),
  onAuthStateChange(callback: (event: string, session: AuthSession | null) => void) {
    listeners.add(callback);
    return { data: { subscription: { unsubscribe: () => listeners.delete(callback) } } };
  },
  signOut: async () => { fixture.session(null); return { error: null }; },
  mfa: {
    enroll: async () => {
      mfaState.calls.push({ action: "enroll" });
      if (mfaState.factors.some((factor) => factor.factor_type === "totp" && factor.status === "unverified")) {
        return { data: null, error: { message: "abandoned enrollment blocks setup" } };
      }
      mfaState.factors.push({ id: "factor-fixture", factor_type: "totp", status: "unverified" });
      return { data: { id: "factor-fixture", totp: {
        qr_code: mfaState.qrCode ?? undefined, secret: "FIXTURESETUPKEY", uri: "otpauth://totp/fixture",
      } }, error: null };
    },
    unenroll: async ({ factorId }: { factorId: string }) => {
      mfaState.calls.push({ action: "unenroll", factorId });
      if (mfaState.unenrollFailure === "throw") throw new Error("fixture cleanup failure");
      if (mfaState.unenrollFailure) return { data: null, error: { message: "fixture cleanup failure" } };
      mfaState.factors = mfaState.factors.filter((factor) => factor.id !== factorId);
      return { data: { id: factorId }, error: null };
    },
    challengeAndVerify: async ({ factorId, code }: { factorId: string; code: string }) => {
      const factor = mfaState.factors.find((item) => item.id === factorId);
      mfaState.verified = !!factor && code === "123456";
      if (mfaState.verified && factor) factor.status = "verified";
      return { data: {}, error: mfaState.verified ? null : { message: "invalid fixture code" } };
    },
    listFactors: async () => {
      mfaState.calls.push({ action: "listFactors" });
      if (mfaState.listFailure === "throw") throw new Error("fixture listing failure");
      if (mfaState.listFailure) return {
        data: null, error: mfaState.listFailure === "missing" ? null : { message: "fixture listing failure" },
      };
      return { data: {
        all: mfaState.factors.map((factor) => ({ ...factor })),
        totp: mfaState.factors.filter((factor) => factor.factor_type === "totp" && factor.status === "verified"),
        phone: mfaState.factors.filter((factor) => factor.factor_type === "phone" && factor.status === "verified"),
      }, error: null };
    },
    getAuthenticatorAssuranceLevel: async () => ({
      data: { currentLevel: mfaState.verified ? "aal2" : "aal1", nextLevel: "aal2" }, error: null,
    }),
  },
} };
export function createBrowserAuth() { return client; }
